        getContents: (id) => getContents(id),
        encodings: { gzip: ".gz" },
        ...overrides,
      });
    });

    t.app.all("/preset/**", (event) => {
      event.res.headers.set("content-length", "5");
      return serveStatic(event, {
        getMeta: (id) => assets[id]?.meta,
        getContents: (id) => getContents(id),
      });
    });
  });

  // RF-01
  it("GET without Range announces byte ranges", async () => {
    const res = await t.fetch("/range/file.txt");
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-length")).toBe("1000");
    expect(await res.text()).toBe(CONTENT);
  });

  it("HEAD without Range announces byte ranges", async () => {
    const res = await t.fetch("/range/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(res.headers.get("content-length")).toBe("1000");
  });

  // RF-03
  it("serves bytes=100-199 as 206", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=100-199" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 100-199/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(res.headers.get("content-type")).toBe("text/plain");
    expect(res.headers.get("etag")).toBe('"abc"');
    expect(res.headers.get("last-modified")).toBe(LAST_MODIFIED);
    expect(await res.text()).toBe(CONTENT.slice(100, 200));
  });

  it("serves bytes=900- to the end", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=900-" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 900-999/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe(CONTENT.slice(900));
  });

  it("serves a suffix range bytes=-100", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=-100" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 900-999/1000");
    expect(await res.text()).toBe(CONTENT.slice(900));
  });

  it("covers the whole asset for a suffix larger than the asset", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=-5000" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-999/1000");
    expect(res.headers.get("content-length")).toBe("1000");
  });

  it("clamps the end to the last byte", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=0-5000" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-999/1000");
  });

  // RF-04
  it("answers 416 for a start past the end", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=1000-1100" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */1000");
    expect(res.headers.get("content-length")).toBe("0");
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe("");
  });

  it("answers 416 for an open range starting at the size", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=1000-" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */1000");
  });

  it("answers 416 for a zero-length suffix", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=-0" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */1000");
  });

  it("answers 416 for any range on an empty asset", async () => {
    const res = await t.fetch("/range/empty.txt", { headers: { range: "bytes=0-" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */0");
    expect(res.headers.get("content-length")).toBe("0");
  });

  // RF-05
  it("HEAD with a valid range returns 206 headers without a body or getContents", async () => {
    const res = await t.fetch("/range/file.txt", {
      method: "HEAD",
      headers: { range: "bytes=0-99" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
    expect(res.headers.get("content-length")).toBe("100");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  it("HEAD with an unsatisfiable range returns 416 without getContents", async () => {
    const res = await t.fetch("/range/file.txt", {
      method: "HEAD",
      headers: { range: "bytes=1000-" },
    });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-range")).toBe("bytes */1000");
    expect(await res.text()).toBe("");
    expect(getContents).not.toHaveBeenCalled();
  });

  // RF-02
  it("ignores a multi-range header", async () => {
    const ranged = await t.fetch("/range/file.txt", { headers: { range: "bytes=0-1,5-6" } });
    const plain = await t.fetch("/range/file.txt");
    expect(ranged.status).toBe(200);
    expect(ranged.headers.get("content-range")).toBeNull();
    expect(ranged.headers.get("content-length")).toBe(plain.headers.get("content-length"));
    expect(await ranged.text()).toBe(CONTENT);
  });

  it("ignores a range with another unit", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "items=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(CONTENT);
  });

  it("ignores a range whose last byte is before the first", async () => {
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=5-2" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(CONTENT);
  });

  it("ignores malformed ranges", async () => {
    for (const range of ["bytes=abc", "bytes=-", "bytes="]) {
      const res = await t.fetch("/range/file.txt", { headers: { range } });
      expect(res.status).toBe(200);
      expect(res.headers.get("content-range")).toBeNull();
      expect(await res.text()).toBe(CONTENT);
    }
  });

  it("ignores Range when the asset size is unknown", async () => {
    const res = await t.fetch("/range/nosize.txt", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(res.headers.get("content-length")).toBeNull();
    expect(await res.text()).toBe(CONTENT);
  });

  it("ignores Range on POST with 405 and Allow", async () => {
    const res = await t.fetch("/range/file.txt", {
      method: "POST",
      headers: { range: "bytes=0-99" },
    });
    expect(res.status).toBe(405);
    expect(res.headers.get("allow")).toBe("GET, HEAD");
  });

  // RF-06 and RF-07
  it("ignores a weak If-Range from the request", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-99", "if-range": 'W/"abc"' },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(CONTENT);
  });

  it("ignores an If-Range with a different ETag", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-99", "if-range": '"xyz"' },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(await res.text()).toBe(CONTENT);
  });

  it("serves 206 when If-Range matches the ETag", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-99", "if-range": '"abc"' },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
  });

  it("ignores Range when the asset ETag is weak", async () => {
    const res = await t.fetch("/range/weak.txt", {
      headers: { range: "bytes=0-99", "if-range": 'W/"abc"' },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("serves 206 when If-Range matches Last-Modified", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-99", "if-range": LAST_MODIFIED },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
  });

  it("ignores Range when If-Range is a different date", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-99", "if-range": "Wed, 15 Nov 2023 22:13:20 GMT" },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("ignores Range when If-Range is an invalid date", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-99", "if-range": "not a date" },
    });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
  });

  it("answers 304 before Range is evaluated", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { range: "bytes=0-99", "if-none-match": '"abc"' },
    });
    expect(res.status).toBe(304);
    expect(res.headers.get("content-range")).toBeNull();
    expect(res.headers.get("accept-ranges")).toBe("bytes");
    expect(await res.text()).toBe("");
  });

  // RF-08
  it("ranges over the precompressed variant and keeps Content-Encoding", async () => {
    const res = await t.fetch("/range/app.js", {
      headers: { "accept-encoding": "gzip", range: "bytes=0-99" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/400");
    expect(res.headers.get("content-length")).toBe("100");
    expect(res.headers.get("content-encoding")).toBe("gzip");
    expect(res.headers.get("content-type")).toBe("text/javascript");
    expect(res.headers.get("vary")).toBe("accept-encoding");
    // Node's fetch decompresses gzip, and a 100-byte slice of a gzip file is not valid gzip.
    if (t.target === "web") {
      expect(await res.text()).toBe("g".repeat(100));
    }
  });

  it("ranges over the original file when no variant exists", async () => {
    const res = await t.fetch("/range/file.txt", {
      headers: { "accept-encoding": "gzip", range: "bytes=0-99" },
    });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 0-99/1000");
    expect(await res.text()).toBe(CONTENT.slice(0, 100));
  });

  // RF-09
  it("counts bytes, not characters, for string bodies", async () => {
    const res = await t.fetch("/range/unicode.txt", { headers: { range: "bytes=1-2" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 1-2/6");
    expect(res.headers.get("content-length")).toBe("2");
    expect(new Uint8Array(await res.arrayBuffer())).toEqual(new Uint8Array([0xc3, 0xa7]));
  });

  it("ignores Range for FormData bodies", async () => {
    const res = await t.fetch("/range/form.txt", { headers: { range: "bytes=0-9" } });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-range")).toBeNull();
    expect(res.headers.get("content-type")).toMatch(/^multipart\/form-data/);
  });

  // RF-10
  it("slices Blob bodies", async () => {
    const res = await t.fetch("/range/blob.txt", { headers: { range: "bytes=10-19" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-range")).toBe("bytes 10-19/1000");
    expect(await res.text()).toBe(CONTENT.slice(10, 20));
  });

  it("stops pulling a ReadableStream origin after the chunk with the last byte", async () => {
    const CHUNK = 64 * 1024;
    const counter = { pulled: 0 };
    const origin = new ReadableStream<Uint8Array>(
      {
        pull(controller) {
          if (counter.pulled >= 160) {
            controller.close();
            return;
          }
          counter.pulled++;
          controller.enqueue(new Uint8Array(CHUNK).fill(counter.pulled));
        },
      },
      { highWaterMark: 0 },
    );
    assets["/range/stream.bin"] = {
      meta: { type: "application/octet-stream", mtime: MTIME, size: 10 * 1024 * 1024 },
      contents: () => origin,
    };

    const res = await t.fetch("/range/stream.bin", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(206);
    expect((await res.arrayBuffer()).byteLength).toBe(100);
    expect(counter.pulled).toBeLessThanOrEqual(1);
  });

  // RF-15
  it("overrides a Content-Length set in options.headers on 206", async () => {
    overrides = { headers: { "content-length": "5" } };
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("100");
  });

  it("overrides a Content-Length set on event.res on 206", async () => {
    const res = await t.fetch("/preset/file.txt", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(206);
    expect(res.headers.get("content-length")).toBe("100");
  });

  it("overrides a Content-Length set in options.headers on 416", async () => {
    overrides = { headers: { "content-length": "5" } };
    const res = await t.fetch("/range/file.txt", { headers: { range: "bytes=1000-" } });
    expect(res.status).toBe(416);
    expect(res.headers.get("content-length")).toBe("0");
  });

  it("keeps the existing Content-Length rule on 200 without Range", async () => {
    overrides = { headers: { "content-length": "5" } };
    const res = await t.fetch("/range/file.txt", { method: "HEAD" });
    expect(res.status).toBe(200);
    expect(res.headers.get("content-length")).toBe("5");
  });

  // RF-11
  it("returns the same 200 response for a range that is ignored", async () => {
    const plain = await t.fetch("/range/file.txt");
    const ignored = await t.fetch("/range/file.txt", { headers: { range: "bytes=5-2" } });
    expect(ignored.status).toBe(plain.status);
    expect(ignored.headers.get("content-length")).toBe(plain.headers.get("content-length"));
    expect(ignored.headers.get("content-type")).toBe(plain.headers.get("content-type"));
    expect(await ignored.text()).toBe(await plain.text());
  });

  it("returns 404 for a missing asset with Range", async () => {
    const res = await t.fetch("/range/missing.txt", { headers: { range: "bytes=0-99" } });
    expect(res.status).toBe(404);
    expect(res.headers.get("accept-ranges")).toBeNull();
  });
});

